class LocalDiagnosticLog{constructor({limit=200,clock=()=>new Date().toISOString()}={}){this.limit=limit;this.clock=clock;this.records=[];}write(level,event,details={},context={}){const record={timestamp:this.clock(),level:String(level),event:String(event),correlationId:context.correlationId||correlationId({seed:event,clock:()=>0}),details:redact(details)};this.records.push(record);if(this.records.length>this.limit)this.records.splice(0,this.records.length-this.limit);return clone(record);}list(){return clone(this.records);}clear(){this.records.length=0;}}
function createBundle({logs=[],environment={},manifest={},errors=[],replay={},consent=false}={}){const payload={schema:'plmr-support-bundle-v1',createdAt:null,uploadAllowed:consent===true,environment:redact(environment),manifest:redact(manifest),logs:redact(logs),errors:redact(errors),replay:redact(replay)};payload.checksum=checksum(payload);return payload;}
function verifyBundle(bundle){if(!bundle||bundle.schema!=='plmr-support-bundle-v1')return false;const copy=clone(bundle),expected=copy.checksum;delete copy.checksum;return checksum(copy)===expected;}
